"""
    Computes the arithmetic mean of a list of numbers.

    >>> average([0.9, 0.9, 0.9, 1.0, 0.8, 0.9])
    0.9
    """
def average(values: Any) -> object {
    return ((1.0 * sum(values)) / len(values)) if values else None;
}

